impl From<PwrightEvaluationErrorDetails> for PublicEvaluationErrorDetails {
    fn from(value: PwrightEvaluationErrorDetails) -> Self {
        match value {
            PwrightEvaluationErrorDetails::Javascript { name, message, stack } => Self::Javascript {
                name,
                message,
                stack,
            },
            PwrightEvaluationErrorDetails::InvalidValue { message } => Self::InvalidValue(message),
            PwrightEvaluationErrorDetails::InvalidBackendResponse { message } => Self::InvalidBackendResponse(message),
            PwrightEvaluationErrorDetails::Backend { message } => Self::Backend(message),
        }
    }
}

impl From<PublicEvaluationErrorDetails> for PwrightEvaluationErrorDetails {
    fn from(value: PublicEvaluationErrorDetails) -> Self {
        match value {
            PublicEvaluationErrorDetails::Javascript { name, message, stack } => Self::Javascript {
                name,
                message,
                stack,
            },
            PublicEvaluationErrorDetails::InvalidValue(message) => Self::InvalidValue { message },
            PublicEvaluationErrorDetails::InvalidBackendResponse(message) => Self::InvalidBackendResponse { message },
            PublicEvaluationErrorDetails::Backend(message) => Self::Backend { message },
        }
    }
}

